// Runtime support copied verbatim into every program generated by RecompRadar.
// It contains the guest memory model, the CPU state and the system call layer (the RecompRadar test calls and, for the
// PlayStation 2 profile, the shared EE memory map and kernel subset from Ps2Runtime.cs).
// It is not compiled into RecompRadar itself; it is embedded as a resource and compiled together with the generated code.
using System.Buffers.Binary;
using System.Runtime.CompilerServices;
using System.Text;
using RecompRadar.Semantics;

namespace RecompRadar.Generated;

public sealed class GuestFaultException : Exception
{
    public GuestFaultException(string message)
        : base(message)
    {
    }
}

/// <summary>Raised by the exit system call; carries the guest's exit code.</summary>
public sealed class ProgramExitException : Exception
{
    public ProgramExitException(int exitCode)
        : base("The guest program exited.")
    {
        ExitCode = exitCode;
    }

    public int ExitCode { get; }
}

/// <summary>Raised when translated code reaches an instruction that could not be translated.</summary>
public sealed class ProgramStopException : Exception
{
    public ProgramStopException(string message)
        : base(message)
    {
    }
}

public sealed class StepLimitException : Exception
{
    public StepLimitException(long executed)
        : base($"Stopped after {executed} guest instructions (limit reached).")
    {
    }
}

public sealed class GuestMemory
{
    public const uint StackBase = 0x7FFE0000;
    public const uint StackSize = 0x10000;

    private sealed class Region
    {
        public uint Base;
        public byte[] Data = [];
        public bool Writable;
        public bool Executable;
    }

    private readonly Region[] _regions;
    private readonly bool _little;
    private readonly Ps2Memory? _ps2;

    public GuestMemory(Stream image, Action<byte> serialOut, out uint entryPoint)
    {
        using var reader = new BinaryReader(image, Encoding.ASCII, leaveOpen: true);
        var magic = reader.ReadBytes(8);
        if (!magic.AsSpan().SequenceEqual("RRIMG2\0\0"u8))
        {
            throw new InvalidDataException("The embedded program image has an unknown format.");
        }

        _little = reader.ReadUInt32() == 0;
        var profile = reader.ReadUInt32();
        entryPoint = reader.ReadUInt32();
        var count = reader.ReadUInt32();
        if (profile == 1)
        {
            _ps2 = new Ps2Memory(_little, message => new GuestFaultException(message), serialOut);
        }

        var regions = new List<Region>();
        for (var i = 0; i < count; i++)
        {
            var baseAddress = reader.ReadUInt32();
            var length = reader.ReadUInt32();
            var flags = reader.ReadUInt32();
            var data = reader.ReadBytes(checked((int)length));
            if (_ps2 is not null)
            {
                _ps2.LoadSegment(baseAddress, data, (flags & 4) != 0);
                continue;
            }

            regions.Add(new Region { Base = baseAddress, Data = data, Writable = (flags & 2) != 0, Executable = (flags & 4) != 0 });
        }

        if (_ps2 is null)
        {
            regions.Add(new Region { Base = StackBase, Data = new byte[StackSize], Writable = true, Executable = false });
        }

        _regions = regions.ToArray();
    }

    /// <summary>True for the PlayStation 2 profile.</summary>
    public bool IsPs2 => _ps2 is not null;

    public uint InitialStackPointer => _ps2 is not null ? Ps2Memory.InitialStackPointer : StackBase + StackSize - 16;

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private Region Find(uint address, int size, out int offset)
    {
        foreach (var r in _regions)
        {
            if (address >= r.Base)
            {
                var delta = address - r.Base;
                var length = (uint)r.Data.Length;
                if (delta <= length && (uint)size <= length - delta)
                {
                    offset = (int)delta;
                    return r;
                }
            }
        }

        offset = 0;
        return null!;
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    private static GuestFaultException Fault(string message) => new(message);

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private Region ForRead(uint address, int size, out int offset)
    {
        if (address % (uint)size != 0)
        {
            throw Fault($"Unaligned {size}-byte read at 0x{address:X8}.");
        }

        return Find(address, size, out offset) ?? throw Fault($"Read of {size} byte(s) at unmapped address 0x{address:X8}.");
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private Region ForWrite(uint address, int size, out int offset)
    {
        if (address % (uint)size != 0)
        {
            throw Fault($"Unaligned {size}-byte write at 0x{address:X8}.");
        }

        var region = Find(address, size, out offset) ?? throw Fault($"Write of {size} byte(s) at unmapped address 0x{address:X8}.");
        if (!region.Writable)
        {
            throw Fault($"Write to read-only memory at 0x{address:X8}.");
        }

        if (region.Executable)
        {
            throw Fault($"Write to executable memory at 0x{address:X8}: self-modifying code is not supported by recompiled programs.");
        }

        return region;
    }

    public uint LoadU8(uint address)
    {
        if (_ps2 is not null)
        {
            return _ps2.Load(address, 1, false);
        }

        var r = ForRead(address, 1, out var o);
        return r.Data[o];
    }

    public uint LoadS8(uint address)
    {
        if (_ps2 is not null)
        {
            return _ps2.Load(address, 1, true);
        }

        var r = ForRead(address, 1, out var o);
        return (uint)(sbyte)r.Data[o];
    }

    public uint LoadU16(uint address)
    {
        if (_ps2 is not null)
        {
            return _ps2.Load(address, 2, false);
        }

        var r = ForRead(address, 2, out var o);
        var span = r.Data.AsSpan(o, 2);
        return _little ? BinaryPrimitives.ReadUInt16LittleEndian(span) : BinaryPrimitives.ReadUInt16BigEndian(span);
    }

    public uint LoadS16(uint address)
    {
        if (_ps2 is not null)
        {
            return _ps2.Load(address, 2, true);
        }

        return (uint)(short)LoadU16(address);
    }

    public uint Load32(uint address)
    {
        if (_ps2 is not null)
        {
            return _ps2.Load(address, 4, false);
        }

        var r = ForRead(address, 4, out var o);
        var span = r.Data.AsSpan(o, 4);
        return _little ? BinaryPrimitives.ReadUInt32LittleEndian(span) : BinaryPrimitives.ReadUInt32BigEndian(span);
    }

    public ulong Load64(uint address)
    {
        if (_ps2 is not null)
        {
            return _ps2.Load64(address);
        }

        var r = ForRead(address, 8, out var o);
        var span = r.Data.AsSpan(o, 8);
        return _little ? BinaryPrimitives.ReadUInt64LittleEndian(span) : BinaryPrimitives.ReadUInt64BigEndian(span);
    }

    public void Store64(uint address, ulong value)
    {
        if (_ps2 is not null)
        {
            _ps2.Store64(address, value);
            return;
        }

        var r = ForWrite(address, 8, out var o);
        var span = r.Data.AsSpan(o, 8);
        if (_little)
        {
            BinaryPrimitives.WriteUInt64LittleEndian(span, value);
        }
        else
        {
            BinaryPrimitives.WriteUInt64BigEndian(span, value);
        }
    }

    public void Store8(uint address, uint value)
    {
        if (_ps2 is not null)
        {
            _ps2.Store(address, 1, value);
            return;
        }

        var r = ForWrite(address, 1, out var o);
        r.Data[o] = (byte)value;
    }

    public void Store16(uint address, uint value)
    {
        if (_ps2 is not null)
        {
            _ps2.Store(address, 2, value);
            return;
        }

        var r = ForWrite(address, 2, out var o);
        var span = r.Data.AsSpan(o, 2);
        if (_little)
        {
            BinaryPrimitives.WriteUInt16LittleEndian(span, (ushort)value);
        }
        else
        {
            BinaryPrimitives.WriteUInt16BigEndian(span, (ushort)value);
        }
    }

    public void Store32(uint address, uint value)
    {
        if (_ps2 is not null)
        {
            _ps2.Store(address, 4, value);
            return;
        }

        var r = ForWrite(address, 4, out var o);
        var span = r.Data.AsSpan(o, 4);
        if (_little)
        {
            BinaryPrimitives.WriteUInt32LittleEndian(span, value);
        }
        else
        {
            BinaryPrimitives.WriteUInt32BigEndian(span, value);
        }
    }

    /// <summary>Reads one byte for the system call layer; -1 when the address is not mapped.</summary>
    public int TryReadByte(uint address)
    {
        if (_ps2 is not null)
        {
            return _ps2.TryReadByte(address);
        }

        var r = Find(address, 1, out var o);
        return r is null ? -1 : r.Data[o];
    }

    public bool TryLoad32(uint address, out uint value)
    {
        if (_ps2 is not null)
        {
            return _ps2.TryLoad32(address, out value);
        }

        value = 0;
        return false;
    }
}

/// <summary>Guest CPU state: the shared virtual register file, memory and the instruction counter.</summary>
public sealed class Cpu
{
    public const int RegisterCount = 128;
    private const int V0 = 2;
    private const int V1 = 3;
    private const int A0 = 4;
    private const int F12 = 64 + 12;

    private readonly StringBuilder _output = new();
    private readonly TextWriter _stdout;
    private int _printed;
    private Ps2Kernel? _kernel;

    public Cpu(TextWriter stdout)
    {
        _stdout = stdout;
    }

    public ulong[] R { get; } = new ulong[RegisterCount];

    public GuestMemory Mem { get; private set; } = null!;

    public long Executed;

    public long Limit = long.MaxValue;

    public string Output => _output.ToString();

    /// <summary>Connects the memory (created with <see cref="Serial"/> as its serial sink) and sets the initial stack pointer.</summary>
    public void Attach(GuestMemory memory)
    {
        Mem = memory;
        R[29] = memory.InitialStackPointer;
        if (memory.IsPs2)
        {
            _kernel = new Ps2Kernel(memory.TryLoad32);
        }
    }

    /// <summary>A byte written to the PS2 serial port.</summary>
    public void Serial(byte value)
    {
        if (_output.Length < PocSystemCalls.MaxOutputChars)
        {
            _output.Append((char)value);
        }
    }

    /// <summary>Writes everything the program printed since the last call to standard output.</summary>
    public void FlushOutput()
    {
        if (_output.Length > _printed)
        {
            _stdout.Write(_output.ToString(_printed, _output.Length - _printed));
            _printed = _output.Length;
        }
    }

    /// <summary>
    /// Performs the system call. Register state must have been written back before the call. Returns the address where the
    /// running thread continues (the instruction after the call, or another thread's resume address).
    /// </summary>
    public uint Syscall(uint continuation)
    {
        if (_kernel is null || (uint)R[V1] == 0)
        {
            TestCall();
            return continuation;
        }

        return Apply(_kernel.Handle(R, continuation));
    }

    /// <summary>Handles a jump to an address that holds no code (a thread function returning to the kernel); false for anything else.</summary>
    public bool TryKernelPc(uint pc, out uint next)
    {
        if (_kernel is null || pc != Ps2Kernel.ThreadExitAddress)
        {
            next = 0;
            return false;
        }

        next = Apply(_kernel.ThreadReturned(R));
        return true;
    }

    private uint Apply(Ps2Result result)
    {
        switch (result.Action)
        {
            case Ps2Action.Exit:
                FlushOutput();
                throw new ProgramExitException(result.ExitCode);
            case Ps2Action.Fault:
                throw new GuestFaultException(result.Message ?? "Kernel call failed.");
            default:
                return result.NextPc;
        }
    }

    private void TestCall()
    {
        var result = PocSystemCalls.Handle((uint)R[V0], (uint)R[A0], (uint)R[F12], address => Mem.TryReadByte(address), _output);
        FlushOutput();

        switch (result.Action)
        {
            case SyscallAction.Exit:
                throw new ProgramExitException(result.ExitCode);
            case SyscallAction.Fault:
                throw new GuestFaultException(result.Message ?? "System call failed.");
            default:
                R[V0] = Sem.Sx(result.ReturnValue);
                break;
        }
    }
}
